effect.shader:
vec3 sat3v(vec3 c){ return clamp(c, vec3(0.0), vec3(1.0)); }
float lum(vec3 c){ return dot(c, vec3(0.2126, 0.7152, 0.0722)); }

// LAYER -> SCREEN: the ramp is built from layer coordinates, so it inherits
// the layer's position, scale and rotation instead of sitting on the frame.
// Positions are anchored on acScreenNorm - the engine's own screen position for
// this fragment - so the anchor never depends on the matrix. Only the DELTA goes
// through acLayerToScreen, and the w=0 multiply cancels the translation, so a
// layer-space offset becomes a screen-space offset exactly. fetchL(acLayerNorm)
// therefore returns texture2DCv(inputImg.texture, acScreenNorm), the engine idiom.
vec2 lpToScreen(vec2 v){ return acScreenNorm + (vec4(v - acLayerNorm, 0.0, 0.0) * acLayerToScreen).xy; }
vec4 fetchL(vec2 lp){ return texture2DCv(inputImg.texture, clamp(lpToScreen(lp), 0.0, 1.0)); }

float h21(vec2 p){ return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123); }

float vnoise(vec2 p){
vec2 i = floor(p);
vec2 f = fract(p);
f = f * f * (3.0 - 2.0 * f);
return mix(mix(h21(i), h21(i + vec2(1.0, 0.0)), f.x),
           mix(h21(i + vec2(0.0, 1.0)), h21(i + vec2(1.0, 1.0)), f.x), f.y);
}

// Octave count comes from a param, but the loop bound stays constant so the
// shader is still GLSL ES 1.0 conformant - the break does the work.
float fbm(vec2 p){
float s = 0.0;
float amp = 0.5;
for (int i = 0; i < 5; i++){
if (float(i) >= float(noiseDetail)) break;
s += amp * vnoise(p);
p *= 2.07;
amp *= 0.5;
}
return s;
}

// Three stops, smooth at softness 1 and hard-stepped at softness 0.
vec3 ramp3(float t){
t = clamp(t, 0.0, 1.0);
if (t < 0.5){
return mix(colA.rgb, colB.rgb, smoothstep(0.0, 1.0, t / 0.5));
}
return mix(colB.rgb, colC.rgb, smoothstep(0.0, 1.0, (t - 0.5) / 0.5));
}

void main(){
vec2 lp  = acLayerNorm;
vec4 src = fetchL(lp);

float a  = max(src.a, 1e-4);
vec3 sc  = src.rgb / a;

float asp = acLayerSize.x / max(acLayerSize.y, 1.0);
vec2  c0  = centre - vec2(0.5);
c0.x *= asp;
vec2  q   = lp - vec2(0.5);
q.x *= asp;
q -= c0;

float ang = radians(angle);
vec2  ax  = vec2(cos(ang), sin(ang));

// ---- ramp coordinate ----------------------------------------------------
float t;
if (shape <= 0){
// Linear: project onto the axis. dot() of a centred coordinate spans -0.5..0.5
// so the +0.5 puts the ramp across the full layer.
t = dot(q, ax) + 0.5;
} else if (shape <= 1){
t = length(q);
} else if (shape <= 2){
t = atan(q.y, q.x) / 6.2831853 + 0.5;
} else if (shape <= 3){
t = abs(q.x) + abs(q.y);
} else if (shape <= 4){
// Mirrored: |projection| folds the ramp back on itself, giving two ramps
// facing each other across the axis.
t = abs(dot(q, ax)) * 2.0;
} else {
t = fbm(q * noiseScale + vec2(acTime * noiseSpeed, acTime * noiseSpeed * 0.6));
}

t = (t - 0.5) * max(spread, 0.05) + 0.5 + midPoint;
t = clamp(t, 0.0, 1.0);

// Softness blends between the smooth ramp and a three-step version of itself.
if (softness < 0.999){
t = mix(floor(t * 3.0 + 0.5) / 3.0, t, clamp(softness, 0.0, 1.0));
}

vec3 ramp = ramp3(t);

// ---- composite ----------------------------------------------------------
vec3 blended;
if (blendMode <= 0){
blended = ramp;
} else if (blendMode <= 1){
blended = sc * ramp * 2.0;
} else if (blendMode <= 2){
blended = vec3(1.0) - (vec3(1.0) - sc) * (vec3(1.0) - ramp);
} else if (blendMode <= 3){
blended = sc + ramp;
} else {
vec3 m = smoothstep(vec3(0.45), vec3(0.55), ramp);
blended = mix(2.0 * sc * ramp + sc * sc * (1.0 - 2.0 * ramp),
              sqrt(max(sc, vec3(0.0))) * (2.0 * ramp - 1.0) + 2.0 * sc * (1.0 - ramp),
              m);
}
blended = sat3v(blended);

vec3  col = mix(sc, blended, clamp(blendAmt, 0.0, 1.0));
float oA  = src.a * opacity;
gl_FragColor = vec4(col * oA, oA);
}
